import{_ as s,C as i,o as r,c as n,a2 as e,E as l}from"./chunks/framework.CHjbm2Wd.js";const b=JSON.parse('{"title":"SIL & HIL","description":"What is real, what is simulated, and how to build a test bed that finds timing bugs.","frontmatter":{"title":"SIL & HIL","description":"What is real, what is simulated, and how to build a test bed that finds timing bugs."},"headers":[],"relativePath":"test/sil-hil.md","filePath":"test/sil-hil.md","lastUpdated":1792993690000}'),o={name:"test/sil-hil.md"};function d(h,t,c,p,u,m){const a=i("Quiz");return r(),n("div",null,[t[0]||(t[0]=e(`<h1 id="sil-hil" tabindex="-1">SIL &amp; HIL <a class="header-anchor" href="#sil-hil" aria-label="Permalink to &quot;SIL &amp; HIL&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Why this matters</p><p>A model-in-the-loop test can prove the math. A software-in-the-loop test can prove the flight code. A hardware-in-the-loop test can prove the interfaces and timing. Each one catches a different class of bug. For a lunar lander, the expensive failures live at the seams.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Distinguish MIL, SIL, PIL, and HIL.</li><li>Design a SIL harness that runs the flight software binary against a plant model.</li><li>Design a HIL setup with real flight hardware and emulated sensors/actuators.</li><li>Inject timing, sensor, and communication faults.</li><li>Decide which test level answers which question.</li></ul><h2 id="the-test-ladder" tabindex="-1">The test ladder <a class="header-anchor" href="#the-test-ladder" aria-label="Permalink to &quot;The test ladder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Flight software</th><th>Plant</th><th>Hardware</th><th>Answers</th></tr></thead><tbody><tr><td><strong>MIL</strong></td><td>Model</td><td>Model</td><td>None</td><td>Does the algorithm work?</td></tr><tr><td><strong>SIL</strong></td><td>Compiled flight code</td><td>Model</td><td>None / host</td><td>Does the code implement the algorithm?</td></tr><tr><td><strong>PIL</strong></td><td>Compiled for target</td><td>Model</td><td>Target processor</td><td>Does the target build behave?</td></tr><tr><td><strong>HIL</strong></td><td>Flight computer</td><td>Real-time model</td><td>Real I/O, emulated sensors/actuators</td><td>Do the interfaces and timing work?</td></tr></tbody></table><p>MIL is fast and flexible. SIL is where you find code-level and interface bugs. PIL is where you find compiler, optimization, and target-library differences. HIL is where you find timing, electrical, and integration bugs. Skipping levels saves time until it does not.</p><h2 id="sil-architecture" tabindex="-1">SIL architecture <a class="header-anchor" href="#sil-architecture" aria-label="Permalink to &quot;SIL architecture&quot;">​</a></h2><p>A practical SIL harness:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────┐      UDP / shared memory      ┌─────────────────────┐</span></span>
<span class="line"><span>│  Flight software    │ &lt;───────────────────────────&gt; │  Plant + sensors    │</span></span>
<span class="line"><span>│  (same binary)      │                               │  (Python/C++/Simulink)│</span></span>
<span class="line"><span>└─────────────────────┘                               └─────────────────────┘</span></span>
<span class="line"><span>          │                                                     │</span></span>
<span class="line"><span>          └────────────────── logs / recorder ──────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Key properties:</p><ul><li><strong>Same flight binary.</strong> Do not recompile a “test version” with different logic.</li><li><strong>Same message formats.</strong> Use the real serialization and units.</li><li><strong>Deterministic time.</strong> A simulated clock, fixed step, and a defined ordering of sensor/command updates.</li><li><strong>Recorded inputs.</strong> Save sensor streams and commands so a failure is reproducible.</li><li><strong>Fault injection.</strong> Drop packets, delay sensors, corrupt checksums, freeze a measurement.</li><li><strong>Automated assertions.</strong> Not just plots.</li></ul><p>A common mistake is to run the flight software as a library inside the plant. That is useful for unit tests, but it does not test the process boundary, the message timing, or the startup sequence. Run the real binary.</p><h2 id="hil-architecture" tabindex="-1">HIL architecture <a class="header-anchor" href="#hil-architecture" aria-label="Permalink to &quot;HIL architecture&quot;">​</a></h2><p>A HIL test bed might look like:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Flight computer ── UART/SpaceWire/Ethernet ── I/O board ── real-time plant</span></span>
<span class="line"><span>       │                                           │</span></span>
<span class="line"><span>       └──────── telemetry / command ──────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>What is real:</p><ul><li>the flight computer and its operating system,</li><li>the flight software binary,</li><li>the I/O drivers and harness,</li><li>the timing and interrupts.</li></ul><p>What is simulated:</p><ul><li>sensors (IMU, star tracker, altimeter, camera),</li><li>actuators (engine, RCS, gimbal),</li><li>the plant dynamics,</li><li>the environment (gravity, terrain, lighting).</li></ul><p>HIL is where you discover that the UART driver drops bytes under load, the sensor timestamp is one cycle late, or the watchdog resets during a flash write.</p><h2 id="time-and-synchronization" tabindex="-1">Time and synchronization <a class="header-anchor" href="#time-and-synchronization" aria-label="Permalink to &quot;Time and synchronization&quot;">​</a></h2><p>A HIL test is only meaningful if time is consistent:</p><ul><li>The plant runs in real time or faster with a synchronized clock.</li><li>Sensor messages carry timestamps that match the plant’s truth time.</li><li>The flight software’s MET and the test bed’s time have a defined offset.</li><li>Command latency is measured, not assumed.</li><li>Logs share a time base.</li></ul><p>If the plant runs at 10× real time but the flight software runs at 1×, you are testing a different system.</p><h2 id="fault-injection" tabindex="-1">Fault injection <a class="header-anchor" href="#fault-injection" aria-label="Permalink to &quot;Fault injection&quot;">​</a></h2><p>Design faults deliberately:</p><table tabindex="0"><thead><tr><th>Fault</th><th>Injection</th><th>Expected response</th></tr></thead><tbody><tr><td>Stale IMU</td><td>Freeze the last sample, keep timestamp old</td><td>Nav detects age, control holds or safes</td></tr><tr><td>Stuck altimeter</td><td>Constant range</td><td>Innovation gate rejects, altitude estimate degrades</td></tr><tr><td>Corrupt command</td><td>Bad checksum / length</td><td>Command rejected, event logged</td></tr><tr><td>Dropped packet</td><td>Skip sequence number</td><td>Timeout/recovery, no silent use</td></tr><tr><td>Delayed sensor</td><td>Add latency</td><td>Nav handles timestamp, controller stays stable</td></tr><tr><td>CPU overload</td><td>Add a busy task</td><td>Deadline monitor, watchdog, graceful degradation</td></tr><tr><td>Power glitch</td><td>Reset the flight computer</td><td>Safe mode, state recovery, no unsafe command</td></tr><tr><td>Actuator stuck</td><td>Freeze RCS valve</td><td>Fault detection, redundancy, abort/divert</td></tr></tbody></table><p>Each fault needs a pass/fail criterion, not just “the vehicle survived.”</p><h2 id="what-hil-does-not-prove" tabindex="-1">What HIL does not prove <a class="header-anchor" href="#what-hil-does-not-prove" aria-label="Permalink to &quot;What HIL does not prove&quot;">​</a></h2><ul><li>It does not prove the plant model is right.</li><li>It does not prove the sensor model matches the real sensor.</li><li>It does not prove the flight software will survive radiation.</li><li>It does not replace flight testing or independent V&amp;V.</li></ul><p>HIL reduces integration risk. It does not eliminate it.</p><h2 id="a-practical-build-order" tabindex="-1">A practical build order <a class="header-anchor" href="#a-practical-build-order" aria-label="Permalink to &quot;A practical build order&quot;">​</a></h2><ol><li><strong>Host unit tests</strong> for math and interfaces.</li><li><strong>SIL</strong> with the flight binary and a simple plant.</li><li><strong>SIL with faults</strong> and automated assertions.</li><li><strong>PIL</strong> on the target processor, if available.</li><li><strong>HIL</strong> with the flight computer and real I/O.</li><li><strong>Mission scenario</strong> with Monte Carlo and hardware faults.</li></ol><p>Do not start with HIL. You will spend weeks debugging the harness instead of the software.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Build a SIL harness that exchanges UDP packets with your flight binary.</li><li>Add a simulated clock and a fixed update order. Log both sides with a shared time base.</li><li>Inject a 200 ms sensor delay and a dropped packet. Does the flight software detect them?</li><li>Add a watchdog and a fault that blocks the main loop. Verify the reset and safe mode.</li><li>Write a HIL test plan for one sensor and one actuator. List what is real, what is simulated, and what could invalidate the test.</li></ol>`,37)),l(a,{question:"What class of bug is most likely to be found in HIL but missed in SIL?",options:"A quaternion sign error|A UART driver dropping bytes under load or a sensor timestamp arriving late|A wrong equation in the guidance law|A unit conversion in a pure function",answer:"1",explanation:"HIL exercises real I/O, drivers, interrupts, and timing. Pure math and unit bugs are usually caught earlier in MIL/SIL or unit tests."}),t[1]||(t[1]=e('<h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://nasa.github.io/cFS/" target="_blank" rel="noreferrer">NASA cFS</a> — a flight framework with test and simulation support.</li><li><a href="https://swehb.nasa.gov/" target="_blank" rel="noreferrer">NASA HIL and V&amp;V resources</a> — software engineering handbook.</li><li><a href="https://www.dspace.com/" target="_blank" rel="noreferrer">dSPACE / Speedgoat HIL</a> — commercial HIL examples (concepts transfer even if you do not use the product).</li><li><a href="https://docs.pytest.org/" target="_blank" rel="noreferrer">Python <code>pytest</code></a> — automate the harness.</li></ul><p>Next: <a href="./python-automation.html">Python test automation</a>.</p>',3))])}const f=s(o,[["render",d]]);export{b as __pageData,f as default};
